import bpy, os, json
from mathutils import Vector
from mathutils.bvhtree import BVHTree
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout')
if not terrain or terrain.type!='MESH': raise RuntimeError('terrain master ausente')
verts=[terrain.matrix_world@v.co for v in terrain.data.vertices]
polys=[tuple(p.vertices) for p in terrain.data.polygons]
bvh=BVHTree.FromPolygons(verts,polys,all_triangles=False)

def rayz(x,y):
    hit=bvh.ray_cast(Vector((x,y,250)),Vector((0,0,-1)),600)
    return None if hit[0] is None else float(hit[0].z)

def zmin(o): return min((o.matrix_world@Vector(c)).z for c in o.bound_box)
def zmax(o): return max((o.matrix_world@Vector(c)).z for c in o.bound_box)
def centerxy(o):
    ps=[o.matrix_world@Vector(c) for c in o.bound_box]
    return ((min(p.x for p in ps)+max(p.x for p in ps))/2,(min(p.y for p in ps)+max(p.y for p in ps))/2)
def anchor(name):
    o=bpy.data.objects.get(name)
    if not o:return {'name':name,'missing':True}
    x,y=centerxy(o); tz=rayz(x,y); lo=zmin(o); hi=zmax(o)
    return {'name':name,'xy':[round(x,4),round(y,4)],'zmin':round(lo,4),'zmax':round(hi,4),'terrain_raycast_z':None if tz is None else round(tz,4),'bottom_gap':None if tz is None else round(lo-tz,4)}
props={k:terrain[k] for k in terrain.keys()}
meshprops={k:terrain.data[k] for k in terrain.data.keys()}
zs=[p.z for p in verts]
anchors=[anchor('V4 | torre documental'),anchor('V4 | hall piso terreo marcador'),anchor('V4 | CB | piso saguão'),anchor('V4 | CB | piso tunel'),anchor('V4 | passadico')]
# amostras ao redor da origem para entender encosta imediata
samples=[]
for x,y in [(0,0),(-5,0),(5,0),(0,-5),(0,5),(-10,-10),(10,10),(20,-20),(30,-30)]:
    z=rayz(x,y);samples.append({'xy':[x,y],'z':None if z is None else round(z,4)})
report={'object':terrain.name,'mesh':terrain.data.name,'verts':len(verts),'polys':len(polys),'world_bounds_z':[round(min(zs),4),round(max(zs),4)],'object_props':props,'mesh_props':meshprops,'anchors':anchors,'local_samples':samples,'scene_vertical_datum':bpy.context.scene.get('world_vertical_datum'),'scene_vertical_note':bpy.context.scene.get('world_vertical_note'),'scene_vertical_delta':bpy.context.scene.get('world_vertical_delta_from_40_blockout_m')}
print('TERRAIN_PROVENANCE_AUDIT_BEGIN')
print(json.dumps(report,ensure_ascii=False,separators=(',',':'),default=str))
print('TERRAIN_PROVENANCE_AUDIT_END')
